package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import android.graphics.drawable.*;import app.layan.quran.view.*;import app.layan.quran.*;import java.io.*;
/** Three actual localized windows for final visual review. */
public final class QiraatPagePreview extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void show(String id,int page,boolean night,String name)throws Exception{
  android.preference.PreferenceManager.getDefaultSharedPreferences(getTargetContext()).edit().putBoolean("nightMode",night).putInt("nightModeTextBrightness",night?160:255).commit();
  QiraatReaderActivity r=(QiraatReaderActivity)startActivitySync(new Intent(getTargetContext(),QiraatReaderActivity.class).putExtra("riwayah",id).putExtra("page",page).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  long end=SystemClock.elapsedRealtime()+120000;boolean ready=false;while(SystemClock.elapsedRealtime()<end){boolean[] value={false};runOnMainSync(()->value[0]=r.currentPageReady());if(value[0]){ready=true;break;}SystemClock.sleep(100);}if(!ready)throw new AssertionError("Page not rendered");
  waitForIdleSync();SystemClock.sleep(500);if(id.equals("warsh")&&page==300&&!night){getUiAutomation().adoptShellPermissionIdentity("android.permission.REORDER_TASKS");try{runOnMainSync(()->r.getSystemService(ActivityManager.class).moveTaskToFront(r.getTaskId(),0));}finally{getUiAutomation().dropShellPermissionIdentity();}boolean focus=false;long focusEnd=SystemClock.elapsedRealtime()+30000;while(SystemClock.elapsedRealtime()<focusEnd){boolean[] v={false};runOnMainSync(()->v[0]=r.hasWindowFocus());if(v[0]){focus=true;break;}SystemClock.sleep(100);}if(!focus)throw new AssertionError("Reader never gained actual input focus");View pager=r.findViewById(QiraatReaderActivity.PAGER);int[] xy=new int[2];runOnMainSync(()->pager.getLocationOnScreen(xy));float start=xy[0]+pager.getWidth()*.1f,stop=xy[0]+pager.getWidth()*.9f,y=xy[1]+pager.getHeight()*.45f;long t=SystemClock.uptimeMillis();touch(MotionEvent.obtain(t,t,0,start,y,0));for(int i=1;i<=12;i++){SystemClock.sleep(40);touch(MotionEvent.obtain(t,SystemClock.uptimeMillis(),2,start+(stop-start)*i/12f,y,0));}touch(MotionEvent.obtain(t,SystemClock.uptimeMillis(),1,stop,y,0));SystemClock.sleep(2000);waitForIdleSync();if(r.currentPage()!=301)throw new AssertionError("RTL touchscreen swipe did not advance to page 301");runOnMainSync(()->r.goToPage(300));SystemClock.sleep(1000);waitForIdleSync();}if(night){HighlightingImageView iv=findImage(r.getWindow().getDecorView());if(iv==null||iv.getColorFilter()!=null)throw new AssertionError("Night image filter must preserve source colours");Bitmap glyphs=((BitmapDrawable)iv.getDrawable()).getBitmap();boolean found=false;for(int yy=0;yy<glyphs.getHeight()&&!found;yy+=2)for(int xx=0;xx<glyphs.getWidth();xx+=2){int pixel=glyphs.getPixel(xx,yy);if(Color.alpha(pixel)>200&&Color.red(pixel)==160&&Color.green(pixel)==160&&Color.blue(pixel)==160){found=true;break;}}if(!found)throw new AssertionError("Night ink did not follow saved brightness setting");}Bitmap b=NativeScreens.capture(this,r);File f=new File(r.getExternalFilesDir("tests"),name+".png");try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();runOnMainSync(r::finish);waitForIdleSync();
 }
 private HighlightingImageView findImage(View v){if(v instanceof HighlightingImageView){Rect rect=new Rect();if(v.getGlobalVisibleRect(rect)&&rect.width()>v.getWidth()/2)return (HighlightingImageView)v;}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){HighlightingImageView found=findImage(((ViewGroup)v).getChildAt(i));if(found!=null)return found;}return null;}
 private void touch(MotionEvent e){try{e.setSource(InputDevice.SOURCE_TOUCHSCREEN);if(!getUiAutomation().injectInputEvent(e,true))throw new AssertionError("Touch rejected");}finally{e.recycle();}}
 public void onStart(){Bundle result=new Bundle();try{show("warsh",300,false,"final-warsh-day");show("qaloon",204,false,"final-qaloon-imala");show("warsh",300,true,"final-warsh-night");android.preference.PreferenceManager.getDefaultSharedPreferences(getTargetContext()).edit().putInt("nightModeTextBrightness",255).commit();result.putString("result","PASS real focused RTL touchscreen swipe and actual Arabic day, Qaloon imala, and colour-preserving night previews with saved brightness setting");finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
